#!/usr/bin/env bash
# Anvil self-contained bootstrap (no HTTP server needed)
set -euo pipefail
GREEN='\033[0;32m'; NC='\033[0m'
info() { echo -e "\[anvil]\ \$*"; }

ANVIL="$HOME/anvil/stubs"
mkdir -p "\/out"
cd "\"

info "Decoding source files..."
echo ''   | base64 -d > winrt_types.h
echo '' | base64 -d > combase_anvil.c
echo ''    | base64 -d > test_combase_anvil.c
echo '' | base64 -d > test_wine_harness.c

info "Installing deps (Wine + GCC + MinGW)..."
sudo apt-get update -qq
sudo apt-get install -y --no-install-recommends gcc mingw-w64 wine wine64 2>&1 | grep -E "Setting up|already" || true

info "Building native tests..."
gcc -O0 -g -Wall -Wextra -Wno-unused-parameter -I. \
    -o out/test_combase combase_anvil.c test_combase_anvil.c

info "Running native tests..."
echo "────────────────────────────────"
./out/test_combase
echo "────────────────────────────────"

info "Cross-compiling combase_anvil.dll..."
x86_64-w64-mingw32-gcc -O2 -Wall -Wno-unused-parameter -I. \
    -shared -Wl,--kill-at \
    -o out/combase_anvil64.dll combase_anvil.c \
    -lkernel32 -lmingwex -lmsvcrt -nostdlib 2>/dev/null \
    && info "DLL OK ✓" || { 
        x86_64-w64-mingw32-gcc -O2 -Wall -Wno-unused-parameter -I. \
            -c -o out/combase_anvil.o combase_anvil.c
        info "Object compiled (full DLL link needs Wine build tree)"
    }

info "Cross-compiling Wine harness..."
x86_64-w64-mingw32-gcc -O0 -o out/test_wine_harness.exe test_wine_harness.c \
    -lkernel32 -luser32 && info "Harness OK ✓" || info "Harness build skipped"

if [[ -f out/combase_anvil64.dll && -f out/test_wine_harness.exe ]]; then
    info "Setting up Wine prefix + DLL override..."
    export WINEPREFIX="$HOME/.wine_anvil" WINEARCH=win64
    WINEDLLOVERRIDES="" wineboot --init 2>/dev/null || true
    cp out/combase_anvil64.dll "\/drive_c/windows/system32/combase.dll"
    info "Running: wine test_wine_harness.exe"
    echo "────────────────────────────────"
    WINEDLLOVERRIDES="combase=b,n" WINEDEBUG=-all \
        wine out/test_wine_harness.exe 2>&1 || true
    echo "────────────────────────────────"
fi
info "Done. See output above for [MISSING FACTORY] call graph."
